def test_only_config_and_passive_adapter_reference_the_execution_package() -> None:
    offenders = []
    for path in _production_modules():
        if path in ALLOWED_READERS:
            continue
        source = path.read_text(encoding="utf-8")
        if path == APP_DIR / "brain" / "hermes_adapter.py":
            # 13B11N-R1/R2 authorizes exactly the P0 untrusted outputs and P1
            # caller-ID vocabulary here. No engine or mode-reader exception.
            tree = ast.parse(source)
            application_imports = [
                (node.module, tuple(alias.name for alias in node.names))
                for node in ast.walk(tree)
                if isinstance(node, ast.ImportFrom) and (node.module or "").startswith("app")
            ]
            assert application_imports == [
                ("app.execution.correlation", ("TurnId", "is_well_formed_id")),
                ("app.execution.types", ("ModelDraft", "ToolProposal")),
            ]
            assert not [node for node in ast.walk(tree) if isinstance(node, ast.Import)
                        and any(alias.name.startswith("app") for alias in node.names)]
            continue
        if "app.execution" in source or "from app import execution" in source:
            offenders.append(str(path.relative_to(PROJECT_ROOT)))
    assert offenders == [], f"execution package imported outside the integration seam: {offenders}"

