def test_zero_production_consumers_or_dynamic_adapter_references():
    consumers = []
    for path in sorted((ROOT / "app").rglob("*.py")):
        if path == MODULE:
            continue
        tree = ast.parse(path.read_text())
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                if any("hermes_adapter" in alias.name for alias in node.names):
                    consumers.append(str(path.relative_to(ROOT)))
            elif isinstance(node, ast.ImportFrom):
                if "hermes_adapter" in (node.module or "") or any(alias.name == "hermes_adapter" for alias in node.names):
                    consumers.append(str(path.relative_to(ROOT)))
            elif isinstance(node, ast.Constant) and type(node.value) is str:
                if "app.brain.hermes_adapter" in node.value:
                    consumers.append(str(path.relative_to(ROOT)))
    assert consumers == ["app/execution/pipeline.py"]
    from tests.execution.pipeline_contract_support import assert_adapter
    assert_adapter()

