def test_exact_import_graph_and_only_reviewed_binding_consumer() -> None:
    path = ROOT / "app/execution/registry_metadata.py"
    tree = ast.parse(path.read_text(encoding="utf-8"))
    imports = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            imports.extend(alias.name for alias in node.names)
        elif isinstance(node, ast.ImportFrom):
            imports.append(node.module or "")
    assert not any(name.startswith(("app.tools", "app.server", "app.brain", "app.logs", "app.execution.dispatch")) for name in imports)
    assert not any(isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id in {"__import__", "eval", "exec"} for node in ast.walk(tree))
    consumers = []
    for other in (ROOT / "app").rglob("*.py"):
        if other == path:
            continue
        if "registry_metadata" in other.read_text(encoding="utf-8"):
            consumers.append(other.relative_to(ROOT).as_posix())
    assert consumers == ["app/execution/binding_projection.py"]
    binding = ROOT / consumers[0]
    binding_imports = [node for node in ast.walk(ast.parse(binding.read_text(encoding="utf-8")))
                       if isinstance(node, ast.ImportFrom) and node.module == "app.execution.registry_metadata"]
    assert len(binding_imports) == 1
    assert {alias.name for alias in binding_imports[0].names} == {
        "RegistryMetadataSnapshotV1", "snapshot_registry_metadata"
    }

