def assert_presence():
    assert PIPELINE.is_file()
    assert not (ROOT/'app/brain/pipeline.py').exists()
    tree=ast.parse(PIPELINE.read_text());defs={n.name for n in tree.body if isinstance(n,(ast.ClassDef,ast.FunctionDef)) and not n.name.startswith('_')}
    defs|={t.id for n in tree.body if isinstance(n,ast.Assign) for t in n.targets if isinstance(t,ast.Name) and not t.id.startswith('_')}
    assert defs==PUBLIC
    entry=next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='run_recorded_turn')
    assert len(entry.args.args)==1 and not entry.args.kwonlyargs and entry.args.vararg is None and entry.args.kwarg is None and not entry.args.defaults
    assert ast.unparse(entry.args.args[0].annotation)=='RecordedTurn' and ast.unparse(entry.returns)=='TurnOutcome'
    allowed={'__future__','collections.abc','dataclasses','datetime','enum','types','typing','app.brain.hermes_adapter','app.execution','app.execution.correlation','app.execution.provenance','app.execution.types'}
    passive={'classifier','router','lane','canonicalize','permissions','obligations','response'}
    for n in ast.walk(tree):
        if isinstance(n,ast.ImportFrom):
            assert n.module in allowed and all(a.name!='*' for a in n.names)
            if n.module=='app.execution':assert {a.name for a in n.names}<=passive
        if isinstance(n,ast.Import):assert all(a.name in allowed for a in n.names)
        if isinstance(n,ast.Call):
            name=ast.unparse(n.func)
            assert name not in {'ToolInvocation','TrustedToolResult','SettledConfirmationProjection','__import__','eval','exec','open'}
            assert not any(x in name for x in ['import_module','dispatch','registry','claim_for_','new_invocation','new_turn','utc_now','datetime.now','datetime.utcnow'])
    for p in (ROOT/'app').rglob('*.py'):
        if p==PIPELINE:continue
        s=p.read_text();assert 'execution.pipeline' not in s and 'run_recorded_turn' not in s, str(p)
        for n in ast.walk(ast.parse(s)):
            if isinstance(n,ast.ImportFrom):assert not any(a.name=='pipeline' for a in n.names)
    assert_adapter()
    for module in BUDGETS:assert_budget(module)
